import{_ as e,o as i,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Tabla Maestra de la División de Eras","description":"","frontmatter":{},"headers":[],"relativePath":"es/70-纪元划分总表.md","filePath":"es/70-纪元划分总表.md","lastUpdated":null}'),s={name:"es/70-纪元划分总表.md"};function r(n,a,l,o,c,u){return i(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="tabla-maestra-de-la-division-de-eras" tabindex="-1">Tabla Maestra de la División de Eras <a class="header-anchor" href="#tabla-maestra-de-la-division-de-eras" aria-label="Permalink to &quot;Tabla Maestra de la División de Eras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>70</td></tr><tr><td>Módulo</td><td>Eras Históricas y Grandes Acontecimientos</td></tr><tr><td>Palabras clave</td><td>División de eras, periodización histórica, ascensión en cuatro etapas, cronología, hitos</td></tr></tbody></table><h2 id="i-los-principios-basicos-de-la-division-de-eras" tabindex="-1">I. Los Principios Básicos de la División de Eras <a class="header-anchor" href="#i-los-principios-basicos-de-la-division-de-eras" aria-label="Permalink to &quot;I. Los Principios Básicos de la División de Eras&quot;">​</a></h2><p>La división de las eras históricas del Universo Hengyuan toma el camino de ascensión en cuatro etapas como marco fundamental, con el estado de desarrollo del mecanismo del Ancla como base central de periodización. Cada era corresponde a una transformación fundamental de la relación entre la civilización y el universo; los límites entre eras no son puntos temporales arbitrarios, sino que están marcados por grandes acontecimientos de importancia universal.</p><p>La división de eras sigue tres principios:</p><ul><li><strong>El principio de correspondencia con la ascensión</strong>: cada gran era corresponde a una etapa del camino de ascensión en cuatro etapas, mientras que los subperíodos dentro de una era corresponden a los avances clave de esa etapa.</li><li><strong>El principio de marcado por acontecimientos</strong>: los puntos de inicio y fin de una era se determinan por grandes acontecimientos emblemáticos, no por simples divisiones iguales del tiempo.</li><li><strong>El principio del estado de la civilización</strong>: cada era recibe su nombre de las características centrales de la civilización de ese período, reflejando las contradicciones principales y la dirección de desarrollo del momento.</li></ul><h2 id="ii-la-tabla-maestra-de-las-eras-historicas-del-universo-hengyuan" tabindex="-1">II. La Tabla Maestra de las Eras Históricas del Universo Hengyuan <a class="header-anchor" href="#ii-la-tabla-maestra-de-las-eras-historicas-del-universo-hengyuan" aria-label="Permalink to &quot;II. La Tabla Maestra de las Eras Históricas del Universo Hengyuan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º de era</th><th>Nombre de la era</th><th>Etapa de ascensión correspondiente</th><th>Acontecimientos marcadores de límites</th><th>Características centrales</th></tr></thead><tbody><tr><td>Primera era</td><td>Era Pre-Ancla</td><td>Pre-ascensión</td><td>Nacimiento del universo → despertar de la primera generación de Anclas</td><td>Cultivo depredador dominante, rupturas frecuentes de civilizaciones</td></tr><tr><td>Segunda era</td><td>Era del Despertar del Ancla</td><td>Inicio de la base de la realidad</td><td>Despertar de las Anclas de primera generación → firma de la Carta Simbiótica</td><td>Mecanismo del Ancla establecido, germinación del pensamiento antipredación</td></tr><tr><td>Tercera era</td><td>Período de Establecimiento del Sistema Simbiótico</td><td>Base de la realidad</td><td>Firma de la Carta Simbiótica → apertura total de los Trescientos Sistemas</td><td>Instituciones simbióticas implementadas, reconstrucción social completada</td></tr><tr><td>Cuarta era</td><td>Era de Apertura y Activación de los Sistemas</td><td>Inicio de la habilitación tecnológica</td><td>Apertura de los Trescientos Sistemas → finalización de la Estrategia de Activación del 20 %</td><td>Cultivo popularizado, avances de la ingeniería de leyes</td></tr><tr><td>Quinta era</td><td>Era de la Primera Ascensión</td><td>Habilitación tecnológica → evolución de la conciencia</td><td>Éxito de la primera ascensión → fundación de la República de las Diez Mil Razas</td><td>Ascensión de la civilización verificada, avance de la interfaz del dominio de la conciencia</td></tr><tr><td>Sexta era</td><td>Era de la República de las Diez Mil Razas</td><td>Evolución de la conciencia</td><td>Fundación de la República de las Diez Mil Razas → inicio de la exploración transplanar</td><td>Unificación de las instituciones de las razas, simbiosis de la conciencia colectiva</td></tr><tr><td>Séptima era</td><td>Era de Exploración Transplanar</td><td>Evolución de la conciencia → simbiosis interestelar</td><td>Inicio de la exploración transplanar → finalización preliminar de la red interestelar</td><td>Grandes descubrimientos de planos, expansión de la red del Ancla</td></tr><tr><td>Octava era</td><td>Era de la Simbiosis Interestelar</td><td>Simbiosis interestelar</td><td>Finalización de la red interestelar → ascensión global del universo</td><td>Simbiosis universal de las razas, ascensión del universo en curso</td></tr></tbody></table><h2 id="iii-duraciones-e-indicadores-clave-de-cada-era" tabindex="-1">III. Duraciones e Indicadores Clave de Cada Era <a class="header-anchor" href="#iii-duraciones-e-indicadores-clave-de-cada-era" aria-label="Permalink to &quot;III. Duraciones e Indicadores Clave de Cada Era&quot;">​</a></h2><p>Dado que el Universo Hengyuan contiene múltiples planos, el flujo del tiempo difiere entre planos; las duraciones de las eras se basan en el tiempo estándar del plano principal:</p><table tabindex="0"><thead><tr><th>Era</th><th>Duración estimada</th><th>Cobertura del Ancla</th><th>Proporción de cultivadores</th><th>Índice de Simbiosis</th></tr></thead><tbody><tr><td>Era Pre-Ancla</td><td>Incognoscible (del orden de miles de millones de años)</td><td>0 %</td><td>&lt;0,01 %</td><td>&lt;10</td></tr><tr><td>Era del Despertar del Ancla</td><td>Varios miles de años</td><td>1 %→10 %</td><td>0,01 %→1 %</td><td>10→30</td></tr><tr><td>Período de Establecimiento del Sistema Simbiótico</td><td>Varios cientos de años</td><td>10 %→40 %</td><td>1 %→10 %</td><td>30→50</td></tr><tr><td>Era de Apertura y Activación de los Sistemas</td><td>Varios cientos de años</td><td>40 %→70 %</td><td>10 %→30 %</td><td>50→70</td></tr><tr><td>Era de la Primera Ascensión</td><td>Varias décadas</td><td>70 %→85 %</td><td>30 %→50 %</td><td>70→80</td></tr><tr><td>Era de la República de las Diez Mil Razas</td><td>Varios cientos de años</td><td>85 %→95 %</td><td>50 %→70 %</td><td>80→90</td></tr><tr><td>Era de Exploración Transplanar</td><td>Varios miles de años</td><td>95 %→99 %</td><td>70 %→90 %</td><td>90→95</td></tr><tr><td>Era de la Simbiosis Interestelar</td><td>En curso</td><td>→100 %</td><td>→100 %</td><td>→100</td></tr></tbody></table><p>La cobertura del Ancla se refiere a la proporción de subregiones de planos donde se ha desplegado el hardware del Ancla; la proporción de cultivadores se refiere a la proporción de formas de vida cubiertas por los sistemas de cultivo formales; el Índice de Simbiosis es un indicador integral que mide el grado de simbiosis de la civilización, con una puntuación máxima de 100.</p><h2 id="iv-la-logica-interna-de-la-evolucion-de-las-eras" tabindex="-1">IV. La Lógica Interna de la Evolución de las Eras <a class="header-anchor" href="#iv-la-logica-interna-de-la-evolucion-de-las-eras" aria-label="Permalink to &quot;IV. La Lógica Interna de la Evolución de las Eras&quot;">​</a></h2><p>La evolución de las eras del Universo Hengyuan no es un transcurso lineal del tiempo, sino un proceso evolutivo en espiral ascendente. Cada era resuelve las contradicciones centrales dejadas por la era anterior mientras cultiva las condiciones de desarrollo de la siguiente:</p><ul><li>La contradicción fundamental de la Era Pre-Ancla era la contradicción entre la depredación y la simbiosis, cuya extremización condujo a la inevitabilidad del despertar del Ancla.</li><li>La Era del Despertar del Ancla resolvió la cuestión de &quot;si existen las Anclas&quot;, pero enfrentó el desafío institucional de &quot;a quién sirven las Anclas&quot;.</li><li>El Período de Establecimiento del Sistema Simbiótico completó la construcción institucional, pero el monopolio de los recursos de cultivo aún restringía la evolución de las masas.</li><li>La Era de Apertura y Activación de los Sistemas rompió el monopolio del cultivo, pero el salto de las capacidades individuales trajo nuevos desafíos éticos y de seguridad.</li><li>La Era de la Primera Ascensión verificó la viabilidad de la ascensión, pero la ascensión de un solo plano era insuficiente para impulsar la evolución global del universo.</li><li>La Era de la República de las Diez Mil Razas unificó las instituciones de la civilización, pero el universo aún contenía una vasta cantidad de planos y razas no contactados.</li><li>La Era de Exploración Transplanar amplió las fronteras de la civilización, pero los planos dispersos necesitaban conexiones interestelares más estrechas.</li><li>La Era de la Simbiosis Interestelar apunta en última instancia a la meta final de la ascensión global del universo.</li></ul><h2 id="v-posicionamiento-de-la-era-actual" tabindex="-1">V. Posicionamiento de la Era Actual <a class="header-anchor" href="#v-posicionamiento-de-la-era-actual" aria-label="Permalink to &quot;V. Posicionamiento de la Era Actual&quot;">​</a></h2><p>Según el estado de desarrollo actual del Universo Hengyuan, la civilización se encuentra en el punto crucial de transición de la Tercera era (Período de Establecimiento del Sistema Simbiótico) a la Cuarta era (Era de Apertura y Activación de los Sistemas). Las instituciones simbióticas se han implementado en los planos principales, el trabajo de apertura de los Trescientos Sistemas avanza de manera integral, y la Estrategia de Activación del 20 % ha entrado en su fase de implementación. Varias tecnologías centrales de la capa de ingeniería de leyes (el Motor de Deducción del Fruto de Multiplicación, los dispositivos de regulación de principios legales espaciales y el Sistema del Espejo de Réplica) han pasado del laboratorio a la producción en masa.</p><p>La tarea central de este período de transición es: garantizar que la apertura de los Trescientos Sistemas beneficie verdaderamente a todas las formas de vida, mientras se cultiva el primer grupo de Potencias Supremas del Plano mediante la Estrategia de Activación del 20 %, acumulando suficiente energía y experiencia para la primera ascensión.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Tabla Maestra de la División de Eras es el marco macro para comprender la evolución histórica del Universo Hengyuan. Condensa la larga historia del universo en ocho eras con clara lógica interna, siendo cada era un escalón necesario hacia la ascensión global del universo. Los documentos posteriores desarrollarán en detalle cada era y los grandes acontecimientos contenidos en ella.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>71-前锚点时代 (La Era Pre-Ancla)</li><li>72-锚点觉醒纪元 (La Era del Despertar del Ancla)</li><li>76-首次升维里程碑 (El Hito de la Primera Ascensión)</li></ul>',22)])])}const v=e(s,[["render",r]]);export{m as __pageData,v as default};
